import {useEffect,useRef,useState} from 'react';
import type {MutableRefObject} from 'react';
import {z} from 'zod';
import {understandingView,planReviewView,sourceRef,workbenchSourceView,workspaceView} from '@devmesh/contracts';
import type {WorkbenchRead,WorkbenchCommand} from './workbench-api.js';
import {WorkbenchAnswers} from './workbench-answers.js';
import {WorkbenchRecovery} from './workbench-recovery.js';
import {WorkbenchApiError} from './workbench-api.js';
import {openWorkbenchLocal} from './workbench-local.js';
import type {DraftContext,LocalCommand} from './workbench-local.js';
import {CloseOriginal,verifyStaleOriginal} from './workbench-original.js';

type Workspace=z.output<typeof workspaceView>;type Understanding=z.output<typeof understandingView>;type Plan=z.output<typeof planReviewView>;type Source=z.output<typeof sourceRef>;type SourceView=z.output<typeof workbenchSourceView>;
type Route={kind:'overview'}|{kind:'understanding'}|{kind:'work';id:string}|{kind:'source';ref:Source;requestId:number;value?:SourceView;error?:string};
type Guard=MutableRefObject<()=>Promise<boolean>>;
const roleName={product:'产品',architect:'架构',developer:'开发',tester:'测试'};
const sourceName=(ref:Source)=>ref.kind==='message'?'查看原始输入':ref.kind==='artifact'?'查看引用材料':`查看需求 ${ref.requirementId} · 版本 ${ref.requirementRevision}`;
const statusName=(value:string)=>({WAITING:'等待处理',READY:'待调度',ACTIVE:'处理中',APPLIED:'已保存结果',FAILED:'处理失败',OUTCOME_UNKNOWN:'处理结果待核实',SUPERSEDED:'已被后续依据替代',RECONCILE:'待核实'}[value]??value);

function PlanDecision({principalId,workspace,plan,read,write,guard,before,onChanged}:{principalId:string;workspace:Workspace;plan:Plan;read:WorkbenchRead;write:WorkbenchCommand;guard:Guard;before:()=>Promise<boolean>;onChanged:(result?:string)=>Promise<void>}){
 const context:Extract<DraftContext,{form:'plan-confirm'}>={principalId,form:'plan-confirm',projectId:workspace.project.projectId,runId:workspace.run.runId,basisRevision:plan.resourceRevision,basis:{planRevision:plan.planRevision,requirementRevision:plan.requirementRevision,reviewHash:plan.reviewHash,...(plan.carryForward?{carryForwardHash:plan.carryForward.sha256}:{})}};
 const [ready,setReady]=useState(false),[busy,setBusy]=useState(false),[agreed,setAgreed]=useState(false),[pending,setPending]=useState<LocalCommand|null>(null),[notice,setNotice]=useState(''),[failure,setFailure]=useState(false);
 const store=useRef<Awaited<ReturnType<typeof openWorkbenchLocal>>|null>(null),original=useRef<LocalCommand|null>(null),draftRevision=useRef(0),working=useRef(false),disposed=useRef(false);
 async function load(){const local=store.current??await openWorkbenchLocal(principalId);if(disposed.current){local.close();return;}store.current=local;const value=await local.load(context);if(disposed.current)return;draftRevision.current=value.draft?.revision??0;original.current=value.pending;setPending(value.pending);setAgreed(false);setFailure(!!value.draft?.closedKey);setReady(true);setNotice(value.pending?'原计划确认结果待核实。':value.draft?.closedKey?'此依据的原确认已关闭，请刷新并审阅当前计划。':'');}
 useEffect(()=>{disposed.current=false;guard.current=async()=>!working.current;void load().catch(()=>{if(!disposed.current){setFailure(true);setNotice('本机确认记录不可用，未发送新确认。请重新读取。');}});return()=>{disposed.current=true;guard.current=async()=>true;store.current?.close();};},[]);
 async function exclusive(work:()=>Promise<void>){if(working.current||disposed.current)return;working.current=true;setBusy(true);try{await work();}catch(e){if(!disposed.current){setAgreed(false);setFailure(!original.current);setNotice(original.current?(e instanceof WorkbenchApiError&&[409,412,422,428].includes(e.status)?'原确认的条件已变化，记录仍保留。请核实原确认，不能改用新请求替代。':'确认结果尚未核实，原请求已保留。'):'本机记录冲突或不可用，未发送新确认。请重新读取。');}}finally{working.current=false;if(!disposed.current)setBusy(false);}}
 async function observe(command:LocalCommand,value:unknown){const observed=await store.current!.observe(command.key,value as Parameters<NonNullable<typeof store.current>['observe']>[1]);if(disposed.current)return;original.current=observed.receipt?.status==='SUCCEEDED'?null:observed;setPending(original.current);setAgreed(false);if(original.current){setNotice('原确认仍待核实，请保留原记录。');return;}setNotice('');working.current=false;await onChanged('计划已明确确认；实施进展与发布另行核实。');}
 async function send(command:LocalCommand){if(command.envelope.kind!=='plan-confirm')throw Error('Wrong command');const e=command.envelope;await observe(command,await write(e.path,{method:'POST',headers:{'content-type':'application/json','idempotency-key':e.key,'if-match':e.ifMatch},body:JSON.stringify(e.body)}));}
 async function closeOriginal(){const p=original.current!;let committed=false;try{const verified=await verifyStaleOriginal(p,read);if(verified.kind==='operation'){await observe(p,verified.value);return;}await store.current!.closeStale(p,verified.proof);committed=true;await load();setNotice('');working.current=false;await onChanged('过期原确认已核实关闭，原审阅依据继续保留。');}catch{setNotice(committed?'关闭已保存在本机，但当前执行尚未刷新，请重新进入。':'尚不能关闭原确认。请核实当前权限、执行依据及原操作；原记录继续保留。');}}
 function confirm(){if(!ready||!agreed||!plan.canConfirm||original.current||failure)return;void exclusive(async()=>{if(!await before()){setNotice('请先处理当前输入区未保存的修改。');return;}const d=await store.current!.save(context,draftRevision.current,{text:'CONFIRM_PLAN',name:''});draftRevision.current=d.revision;const q=await store.current!.enqueue(context,d.revision);draftRevision.current=q.draft.revision;original.current=q.command;setPending(q.command);setAgreed(false);await send(q.command);});}
 return <section className="notice" aria-label="计划确认"><h3>确认当前计划</h3>{notice&&<p role="status">{notice}</p>}{pending?<><p>刷新不会自动确认。原确认对应计划 {pending.envelope.context.form==='plan-confirm'?pending.envelope.context.basis.planRevision:'—'}，仅可核实或继续同一请求。</p><div className="actions"><button disabled={busy} onClick={()=>void exclusive(async()=>{const p=original.current!;try{await observe(p,await read('/api/v1/operations/lookup?scope='+encodeURIComponent(p.envelope.scope)+'&key='+p.key));}catch(e){if(e instanceof WorkbenchApiError&&e.status===404){setNotice('当前未查到原确认。请保留原记录，可明确使用原请求继续确认。');return;}throw e;}})}>核实原计划确认</button><button disabled={busy} onClick={()=>void exclusive(()=>send(pending))}>使用原请求继续确认计划</button></div><CloseOriginal key={pending.key} busy={busy} onClose={()=>void exclusive(closeOriginal)}/></>:<><label><input type="checkbox" checked={agreed} disabled={!ready||busy||failure||!plan.canConfirm} onChange={e=>setAgreed(e.target.checked)}/>我已审阅当前计划、需求依据与沿用结果，明确同意按此计划实施。</label><p className="muted">打开、刷新和查看依赖图均不会确认计划。</p><button className="primary" disabled={!ready||busy||failure||!agreed||!plan.canConfirm} onClick={confirm}>明确确认计划</button></>}{failure&&<button disabled={busy} onClick={()=>void exclusive(load)}>重新读取本机确认记录</button>}</section>;
}

function DependencyGraph({plan,open}:{plan:Plan;open:(id:string)=>void}){
 const works=new Map(plan.plan.works.map(w=>[w.workId,w])),positions=new Map<string,{x:number;y:number}>(),counts=new Map<number,number>();for(const node of plan.topology){const n=counts.get(node.layer)??0;counts.set(node.layer,n+1);positions.set(node.workId,{x:20+node.layer*190,y:20+n*88});}
 const width=Math.max(260,...[...positions.values()].map(p=>p.x+170)),height=Math.max(100,...[...positions.values()].map(p=>p.y+68));
 return <section aria-label="计划依赖图"><h3>工作依赖图</h3>{!plan.topology.length?<p>此计划的依赖图暂不可用，请核对下方校验记录。</p>:<div className="dag-scroll"><svg width={width} height={height} role="group" aria-label="按依赖层排列的工作"><defs><marker id="dag-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10Z" fill="#587067"/></marker></defs>{plan.plan.works.flatMap(w=>w.dependencies.map(d=>{const from=positions.get(d.workId),to=positions.get(w.workId);return from&&to?<path key={d.workId+'>'+w.workId} d={`M${from.x+160} ${from.y+28} C${from.x+180} ${from.y+28} ${to.x-20} ${to.y+28} ${to.x} ${to.y+28}`} fill="none" stroke="#587067" markerEnd="url(#dag-arrow)"/>:null;}))}{plan.topology.map(node=>{const p=positions.get(node.workId)!,w=works.get(node.workId);return w?<g key={w.workId} role="button" tabIndex={0} aria-label={'查看工作 '+w.workId} onClick={()=>open(w.workId)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(w.workId);}}}><title>{w.workId+'：'+w.goal}</title><rect x={p.x} y={p.y} width="160" height="56" rx="9" fill="#fff" stroke="#7b9c89"/><text x={p.x+10} y={p.y+21} fill="#245248">{roleName[w.role]} · {w.workId.slice(0,15)}</text><text x={p.x+10} y={p.y+41} fill="#587067">{w.goal.slice(0,11)}{w.goal.length>11?'…':''}</text></g>:null;})}</svg></div>}</section>;
}

export function WorkbenchPlanning({principalId,workspace,read,write,guard,before,onChanged}:{principalId:string;workspace:Workspace;read:WorkbenchRead;write:WorkbenchCommand|null;guard:Guard;before:()=>Promise<boolean>;onChanged:(result?:string)=>Promise<void>}){
 const [understanding,setUnderstanding]=useState<Understanding|null>(null),[plan,setPlan]=useState<Plan|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[stack,setStack]=useState<Route[]>([{kind:'overview'}]);
 const latest=useRef({read,write,before,onChanged}),generation=useRef(0),sourceSequence=useRef(0),disposed=useRef(false);latest.current={read,write,before,onChanged};
 async function reload(){const token=++generation.current,run=workspace.run;setLoading(true);setError('');try{
   const [u,p]=await Promise.all([latest.current.read('/api/v1/runs/'+run.runId+'/understanding'+(run.currentRequirementRevision?'?requirementRevision='+run.currentRequirementRevision:'')),run.currentPlanRevision?latest.current.read('/api/v1/runs/'+run.runId+'/plans?revision='+run.currentPlanRevision):Promise.resolve(null)]);
   if(disposed.current||token!==generation.current)return;const understood=understandingView.parse(u),review=p===null?null:planReviewView.parse(p);
   if(understood.runId!==run.runId||understood.requirementRevision!==run.currentRequirementRevision||review&&(review.runId!==run.runId||review.projectId!==workspace.project.projectId||review.planRevision!==run.currentPlanRevision||review.resourceRevision!==run.resourceRevision))throw Error('Planning basis changed');
   setUnderstanding(understood);setPlan(review);
  }catch{if(!disposed.current&&token===generation.current){setError('理解或计划依据暂不可读，请刷新当前执行后重试。');setUnderstanding(null);setPlan(null);}}finally{if(!disposed.current&&token===generation.current)setLoading(false);}}
 useEffect(()=>{disposed.current=false;setStack(old=>old.map(r=>r.kind==='source'&&!r.value&&!r.error?{...r,error:'执行已刷新，请返回后重新打开此来源。'}:r));void reload();return()=>{disposed.current=true;generation.current++;sourceSequence.current++;};},[workspace]);
 const top=stack.at(-1)!,currentReview=plan?.mode==='current'&&plan.resourceRevision===workspace.run.resourceRevision&&plan.planRevision===workspace.run.currentPlanRevision&&plan.requirementRevision===workspace.run.currentRequirementRevision;
 async function push(route:Route){if(!await guard.current()){setError('回答尚未保存或原提交正在处理，请先处理当前表单。');return false;}if(stack.length>=16){setError('来源层级已达上限，请先返回上一级。');return false;}setStack(old=>old.length>=16?old:[...old,route]);return true;}
 function updateSource(route:Extract<Route,{kind:'source'}>){setStack(old=>{const current=old.at(-1);return current?.kind==='source'&&current.requestId===route.requestId?[...old.slice(0,-1),route]:old;});}
 async function openSource(input:Source){const ref=sourceRef.parse(input),requestId=++sourceSequence.current,token=generation.current;if(!await push({kind:'source',ref,requestId}))return;try{const value=workbenchSourceView.parse(await latest.current.read('/api/v1/runs/'+workspace.run.runId+'/sources?ref='+encodeURIComponent(JSON.stringify(ref))));if(disposed.current||token!==generation.current)return;if(value.runId!==workspace.run.runId||JSON.stringify(value.ref)!==JSON.stringify(ref))throw Error('Source differs');updateSource({kind:'source',ref,requestId,value});}catch{if(!disposed.current&&token===generation.current)updateSource({kind:'source',ref,requestId,error:'此来源不存在、已不可见或无法按原依据读取。'});}}
 const sources=(refs:readonly Source[])=><div className="source-links">{refs.map((ref,i)=><button key={i} onClick={()=>void openSource(ref)}>{sourceName(ref)}</button>)}</div>;
 const requirementCard=(r:NonNullable<Understanding['understanding']>['requirements'][number])=><article key={r.id} className="card"><h3>{r.id}</h3><p>{r.statement}</p><h4>验收条件</h4><ul>{r.acceptance.map((item,i)=><li key={i}>{item}</li>)}</ul>{sources(r.sourceRefs)}</article>;
 const openWork=(id:string)=>push({kind:'work',id});
 const work=top.kind==='work'?plan?.plan.works.find(w=>w.workId===top.id):null;
 return <div className="planning"><nav aria-label="任务详情导航"><button disabled={stack.length===1} onClick={()=>void(async()=>{if(!await guard.current()){setError('回答尚未保存或原提交正在处理，请先处理当前表单。');return;}sourceSequence.current++;setStack(old=>old.length>1?old.slice(0,-1):old);})()}>返回上一级</button><span className="muted">{top.kind==='overview'?'任务总览':top.kind==='understanding'?'需求理解':top.kind==='work'?'工作详情':'来源'}</span></nav>{loading&&<p role="status">正在读取理解与计划…</p>}{error&&<p role="alert" className="notice">{error}</p>}
  {top.kind==='source'?<section aria-label="来源详情"><h2>{top.value?.label??sourceName(top.ref)}</h2>{top.error?<p role="alert">{top.error}</p>:!top.value?<p role="status">正在读取原来源…</p>:top.value.body.kind==='text'?<pre className="source-text">{top.value.body.text}</pre>:requirementCard(top.value.body.requirement)}</section>:top.kind==='work'?<section aria-label="工作详情">{!work?<p>当前读取的计划中没有此工作，请返回核对依据。</p>:<><h2>{roleName[work.role]}工作</h2><p>{work.goal}</p><p className="muted">工作 {work.workId} · 版本 {work.workRevision}</p><h3>前置工作</h3>{work.dependencies.length?work.dependencies.map(d=><p key={d.workId}><button onClick={()=>openWork(d.workId)}>{d.workId}</button> · {d.requiredOutcome==='success'?'须成功':'允许带发现完成'}</p>):<p>无前置工作。</p>}<h3>需求来源</h3>{sources(work.requirementIds.map(requirementId=>({kind:'requirement',requirementId,requirementRevision:plan!.requirementRevision})))}<h3>工作输入</h3>{work.inputRefs.length?work.inputRefs.map((ref,i)=><div key={i}>{ref.kind==='artifact'?sources([{...ref,kind:'artifact'}]):<button onClick={()=>openWork(ref.workId)}>查看 {ref.workId} 的 {ref.outputSlot} 输出约定</button>}</div>):<p>没有额外输入引用。</p>}<h3>预期输出</h3><ul>{work.outputSpec.map(s=><li key={s.slot}>{s.slot} · {s.schemaId}</li>)}</ul><h3>完成检查</h3><ul>{work.completionChecks.map((c,i)=><li key={i}>{c.kind}{'checkId'in c?' · '+c.checkId:'outputSlot'in c?' · '+c.outputSlot:''}</li>)}</ul><h3>写入范围</h3>{work.writeScope.length?<ul>{work.writeScope.map(s=><li key={s}>{s}</li>)}</ul>:<p>此工作不写入代码文件。</p>}<details><summary>资源估计</summary><p>CPU {work.estimatedResources.cpu} · 内存 {work.estimatedResources.memoryMiB} MiB · 超时 {work.estimatedResources.timeoutMs} ms</p></details></>}</section>:top.kind==='understanding'?<section aria-label="需求理解详情"><h2>需求理解{understanding?.requirementRevision?' · 版本 '+understanding.requirementRevision:''}</h2>{!understanding?.understanding?<p>尚无已保存的需求理解。</p>:<>{understanding.understanding.requirements.map(requirementCard)}{!!understanding.understanding.assumptions.length&&<><h3>假设</h3><ul>{understanding.understanding.assumptions.map((a,i)=><li key={i}>{a}</li>)}</ul></>}{understanding.understanding.conflicts.map(c=><article key={c.id} className="notice"><h3>待澄清冲突</h3><p>{c.description}</p>{sources(c.sourceRefs)}</article>)}</>}<h3>澄清问题</h3>{understanding?.questions.length?understanding.questions.map(q=><article key={q.questionId+':'+q.questionRevision} className="card"><h4>{q.content.prompt}</h4><p>{q.content.required?'必要问题':'可选问题'} · {q.state==='OPEN'?'待回答':q.state==='ANSWERED'?'已保存回答':'旧版本'} · 版本 {q.questionRevision}</p><p>{q.content.reason}</p>{q.content.options.length>0&&<ul>{q.content.options.map(o=><li key={o.id}>{o.label}</li>)}</ul>}{q.answer&&<p>已保存回答：{typeof q.answer.value==='string'?q.answer.value:JSON.stringify(q.answer.value)}</p>}{sources(q.content.sourceRefs)}</article>):<p>当前版本没有已保存的问题。</p>}{write&&workspace.mode==='current'&&(understanding?.requirementRevision?<WorkbenchAnswers key={JSON.stringify([workspace.run.resourceRevision,understanding.requirementRevision,understanding.questions.map(q=>[q.questionId,q.questionRevision])])} principalId={principalId} workspace={workspace} understanding={understanding} read={read} write={write} guard={guard} before={before} onChanged={onChanged}/>:<WorkbenchRecovery key={JSON.stringify([workspace.run.resourceRevision,'questions-answer'])} principalId={principalId} workspace={workspace} form="questions-answer" read={read} write={write} guard={guard} onChanged={onChanged}/>)}</section>:<section aria-label="理解与计划"><h2>需求与计划</h2><p>{workspace.preparation.pending?'已有输入等待后台处理。':'当前没有等待分析的输入。'}</p><button onClick={()=>push({kind:'understanding'})}>查看理解与问题</button>{understanding&&<details><summary>分析进展</summary><p>等待生成理解的输入：{understanding.pendingInputCount}</p>{understanding.jobs.map(j=><p key={j.jobId}>{j.role==='product'?'需求分析':'计划生成'} · {statusName(j.state)}{j.errorCode?' · '+j.errorCode:''}</p>)}</details>}{!plan?<p>{loading?'正在读取当前计划…':error?'当前计划暂不可读，请刷新后重试。':'尚无已保存的计划。理解和计划生成需要可用的模型配置。'}</p>:<><h3>计划 {plan.planRevision} · 需求依据 {plan.requirementRevision}</h3><p>{plan.confirmation?'已明确确认此计划。':plan.mode==='history'?'此计划依据已变化，只供核对。':plan.canConfirm?'当前计划具备确认条件，仍须明确审阅与确认。':'当前不可确认，请核对必要问题、输入处理及计划校验。'}</p>{!!plan.issues.length&&<section aria-label="计划校验记录"><h4>需要处理的校验项</h4><ul>{plan.issues.map((issue,i)=><li key={i}>{issue.code} · {issue.path}{issue.workId&&<button onClick={()=>openWork(issue.workId!)}>查看 {issue.workId}</button>}</li>)}</ul></section>}<DependencyGraph plan={plan} open={openWork}/><h3>计划工作</h3>{plan.plan.works.map(w=><article key={w.workId}><button onClick={()=>openWork(w.workId)}>{roleName[w.role]} · {w.goal}</button><p className="muted">{w.workId} · 前置 {w.dependencies.length} 项</p></article>)}{plan.carryForward&&<details><summary>沿用已核验结果 {plan.carryForward.results.length} 项</summary>{plan.carryForward.results.map(r=><p key={r.workId}>{r.workId} · 版本 {r.workRevision} · {r.outcome}</p>)}</details>}<details><summary>准确审阅依据</summary><p className="hash">{plan.reviewHash}</p><p className="hash">代码基线 {plan.baseCommit}</p></details></>}{write&&workspace.mode==='current'&&(currentReview?<PlanDecision key={JSON.stringify([plan.resourceRevision,plan.planRevision,plan.reviewHash,plan.carryForward?.sha256])} principalId={principalId} workspace={workspace} plan={plan} read={read} write={write} guard={guard} before={before} onChanged={onChanged}/>:<WorkbenchRecovery key={JSON.stringify([workspace.run.resourceRevision,plan?.reviewHash??null,'plan-confirm'])} principalId={principalId} workspace={workspace} form="plan-confirm" read={read} write={write} guard={guard} onChanged={onChanged}/>)}</section>}
 </div>;
}
